// Initialize an array to hold the output
const output = [];

for (let item of $input.all()) {
  // Get the captions array
  let captions = item.json.captions;

  // Join the captions into a single string
  let rawText = captions.join(" ");

  // Step 1: Decode HTML entities (e.g., &#39; to ')
  let decodedText = rawText
    .replace(/&#39;/g, "'") // Specifically handle apostrophe HTML entity
    .replace(/&quot;/g, '"') // Handle double quotes
    .replace(/&amp;/g, "&") // Handle ampersands
    .replace(/&#\d+;/g, match => { // Handle any other numeric entities
      const code = parseInt(match.slice(2, -1));
      return String.fromCharCode(code);
    });

  // Step 2: Normalize special characters and clean up
  let normalizedText = decodedText
    .replace(/[\u2018\u2019]/g, "'") // Replace curly single quotes with straight '
    .replace(/[\u201C\u201D]/g, '"') // Replace curly double quotes with straight "
    .replace(/[\u2026]/g, "...") // Replace ellipsis with three dots
    .replace(/[^\w\s.,!?'-]/g, " ") // Remove other non-standard characters, keep basic punctuation
    .replace(/\s+/g, " ") // Collapse multiple spaces into one
    .trim();

  // Step 3: Split into potential sentences based on common sentence-ending punctuation
  let sentences = normalizedText
    .split(/([.!?])\s+/)
    .filter(Boolean); // Split on .!? followed by space, keep delimiters

  // Step 4: Reconstruct the text with proper capitalization and spacing
  let cleanedText = "";
  for (let i = 0; i < sentences.length; i++) {
    let part = sentences[i].trim();
    if (part) {
      // Capitalize the first letter of each sentence
      if (part.match(/^[a-z]/i)) {
        part = part.charAt(0).toUpperCase() + part.slice(1);
      }
      cleanedText += part;
      // Add a space after sentence-ending punctuation, unless it's the last part
      if (part.match(/[.!?]$/) && i < sentences.length - 1) {
        cleanedText += " ";
      }
    }
  }

  // Ensure the text ends with a period if it doesn’t already end with punctuation
  if (!cleanedText.match(/[.!?]$/)) {
    cleanedText += ".";
  }

  // Create the response object with just videoId and transcript
  const response = {
    json: {
      "videoId": item.json.videoId,
      "transcript": cleanedText
    }
  };

  // Push the response to the output array
  output.push(response);
}

// Return the array of items
return output;
